    if (!trimmed)
        return { category: 'literal', reason: 'empty' };
    if (RE_PATH_PREFIX.test(trimmed) ||
        RE_REL_PATH.test(trimmed) ||
        (RE_SLASH.test(trimmed) && !RE_HAS_WHITESPACE.test(trimmed))) {
        return { category: 'literal', reason: 'filesystem path' };
    }
    if (RE_REGEX_META.test(trimmed) && !RE_HAS_WHITESPACE.test(trimmed)) {
        return { category: 'literal', reason: 'regex metacharacters, no whitespace' };
    }
    if (RE_SINGLE_IDENTIFIER.test(trimmed) && !RE_HAS_WHITESPACE.test(trimmed)) {
        return { category: 'literal', reason: 'single identifier' };
    }
