        return { category: 'literal', reason: 'error message shape', wordCount };
    }
    if (RE_QUESTION_WORD.test(trimmed)) {
        return { category: 'conceptual_high', reason: 'English question word', wordCount };
    }
    if (RE_DESCRIPTIVE.test(trimmed)) {
        return { category: 'conceptual_high', reason: 'descriptive phrasing', wordCount };
    }
    if (wordCount >= 4 && !RE_META_OR_PUNCT.test(trimmed)) {
        return { category: 'conceptual_high', reason: '4+ words, no metachars', wordCount };
