    try {
      const value = JSON.parse(storage.getItem(key) || '{}');
      return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    } catch { return {}; }
  }
  function clear(id) {
    const drafts = load();
    if (!(id in drafts)) return;
    delete drafts[id];
    try { storage.setItem(key, JSON.stringify(drafts)); } catch {}
  }
