// Inspect the static relative import graph rooted at the selected generated modules.
import { posix as path } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
function inspect(files, entries, parseModule) {
  const queue = [...entries].filter(file => file.endsWith('.mjs')).sort();
  const seen = new Set();
  const missing = [];
  while (queue.length) {
    const name = queue.shift();
    if (seen.has(name)) continue;
    seen.add(name);
    if (!files.has(name)) { missing.push(name); continue; }
    const [imports] = parseModule(files.get(name), name);
    for (const item of imports) {
      if (!item.n?.startsWith('.')) continue;
      const importer = pathToFileURL(path.join('/bundle', name));
      const target = path.relative('/bundle', fileURLToPath(new URL(item.n, importer)));
      if (!files.has(target)) missing.push(target);
      else if (target.endsWith('.mjs') && !seen.has(target)) queue.push(target);
    }
  }
  return { missing };
}
export function checkGeneratedModules(files, entries, parseModule) {
  try {
    const report = inspect(files, entries, parseModule);
    return { code: report.missing.length ? 1 : 0, report };
  } catch {
    return { code: 1, report: null };
  }
}

