                path = '/' + path;
            return config.url + path;
        }
        return path;
    });
    images.forEach(function (path) {
        result += og('og:image', path);
    });
    if (updated) {
        if ((moment.isMoment(updated) || moment.isDate(updated)) && !isNaN(updated.valueOf())) {
            result += og('og:updated_time', updated.toISOString());
        }
    }
