    result += meta('twitter:title', title);
    if (description) {
        result += meta('twitter:description', description);
    }
    if (images.length) {
        result += meta('twitter:image', images[0]);
    }
    if (options.twitter_id) {
        var twitterId = options.twitter_id;
        if (twitterId[0] !== '@')
